import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_toLocale_TriageGen4Test {











    @Test
    public void testToLocale_MissingUnderscore() {
        // len is 3, but if len was 5 and charAt(2) != '_'
        // The code checks len < 5 first, so we need len >= 5 to hit the underscore check
        try {
            LocaleUtils.toLocale("enUS"); // len 4, hits len < 5
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: enUS", e.getMessage());
        }

        // len 5, check charAt(2)
        try {
            LocaleUtils.toLocale("en-US");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en-US", e.getMessage());
        }
    }










}

