public class LocaleUtils_toLocale_TriageGen4Test {













    @Test
    public void testToLocale_LanguageAndVariantWithEmptyCountry() {
        // Test logic: if (ch3 == '_') return new Locale(str.substring(0, 2), "", str.substring(4));
        // Input: "en__US" -> length 6. ch3 is '_'
        Locale result = LocaleUtils.toLocale("en__US");
        assertEquals(new Locale("en", "", "US"), result);
    }








