public class LocaleUtils_toLocale_TriageGen4Test {





















    @Test
    public void testToLocale_LanguageCountryVariant() {
        // len 7 or more
        Locale result = LocaleUtils.toLocale("en_US_FR");
        assertEquals(new Locale("en", "US", "FR"), result);

        Locale resultLong = LocaleUtils.toLocale("en_US_variant");
        assertEquals(new Locale("en", "US", "variant"), resultLong);
    }
}
